const convPath = c => c.cid ? `${cidRoot(c.cid)}/${msgFor.code}/${c.cid}` : `dm/${msgFor.code}/${c.tid}/${c.fam}`;
const convHash = c => c.cid ? `#/messages/with/${sdOther(c.cid)}` : `#/messages/${c.tid}/${c.fam}`;
