    const views = [];
    if (mine) views.push({ b: code, items: mine, topic: '' });
    if (all && mine) { const hers = new Set(mine.map(it => it.key)); views.push({ b: code + '|club', items: all.filter(it => !hers.has(it.key)), topic: 'news' }); }
