  const last = Object.values(t.events || {}).filter(e => e && e.kind === 'practice' && hm(e.start) && hm(e.end) && minOf(e.end) > minOf(e.start))
    .sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))[0];
