    rows.push([f ? f.name : x.venue, pt ? pt.name : '', DAYS_LONG[weekdayOf(x.date)], `${minHm(x.a)}-${minHm(x.b)}`, team, x.kind === 'practice' ? kindOf(x.ptype).label : x.kind === 'game' ? 'Game' : 'Session', span[0], span[1]].map(csvCell).join(','));
