/* The charts' scrubber: a finger down on a chart reads it there, and dragged
   along it follows (vertical scrolling is left to the page by touch-action:
   pan-y, so a thumb going down the screen is still a scroll). A mouse reads
   as it passes. The chart holds the pointer so a drag past its edge keeps
   reading the end. */
{
  const chartOf = e => e.target && e.target.closest && e.target.closest('svg.lchart');
  let held = null;
  document.addEventListener('pointerdown', e => {
    const svg = chartOf(e); if (!svg) return;
    held = e.pointerId;
    try { svg.setPointerCapture(e.pointerId); } catch (x) { }
    lcScrub(svg, e.clientX);
  });
  document.addEventListener('pointermove', e => {
    const svg = chartOf(e); if (!svg) return;
    if (held !== e.pointerId && e.pointerType !== 'mouse') return;
    lcScrub(svg, e.clientX);
  });
  const drop = e => { if (held === e.pointerId) held = null; };
  document.addEventListener('pointerup', drop);
  document.addEventListener('pointercancel', drop);
}
/* Time boxes (m:ss) keep their colon. On a phone's number pad there is no colon
   key, so a deleted colon could not be typed back and the time stopped parsing.
   Instead the box holds digits only and draws the colon itself: the last two
   digits are seconds, so typing 2 3 1 0 reads 23:10. Backspace over the colon
   deletes the digit before it, which is what she meant. */
function clockFormat(value, caret) {
  const v = String(value || '');
  const before = v.slice(0, caret == null ? v.length : caret).replace(/\D/g, '').length;
  let d = v.replace(/\D/g, '').replace(/^0+(?=\d{3})/, '');
  if (!d) return { value: '', caret: 0 };
  const lost = v.replace(/\D/g, '').length - d.length; // leading zeros trimmed
  d = d.padStart(3, '0');
  const out = d.slice(0, -2) + ':' + d.slice(-2);
  // put the caret back after the same number of digits it was after
  let want = Math.max(0, before - lost) + (d.length - (v.replace(/\D/g, '').length - lost));
  let pos = 0, seen = 0;
  while (pos < out.length && seen < want) { if (out[pos] !== ':') seen++; pos++; }
  return { value: out, caret: pos };
}
document.addEventListener('keydown', e => {
  const t = e.target;
  if (!t || !t.dataset || t.dataset.clock == null || t.selectionStart !== t.selectionEnd) return;
  const i = t.selectionStart;
  if (e.key === 'Backspace' && t.value[i - 1] === ':') t.setSelectionRange(i - 1, i - 1);
  else if (e.key === 'Delete' && t.value[i] === ':') t.setSelectionRange(i + 1, i + 1);
});
document.addEventListener('input', e => {
  const t = e.target;
  if (!t || !t.dataset || t.dataset.clock == null) return;
  const r = clockFormat(t.value, t.selectionStart);
  if (r.value === t.value) return;
  t.value = r.value;
  try { t.setSelectionRange(r.caret, r.caret); } catch (_) { /* not focused */ }
});


/* ---------------- routing ---------------- */
/* Hash routing rather than real paths: GitHub Pages has no rewrites, so
   /admin/clubname would need a 404.html redirect hack. The hash gives the same
   readable hierarchy, real back and forward, and links that survive a reload. */
function uiToHash() {
  normView();
  const t = ui.teamId, m = ui.matchId;
  if (ui.view === 'game' && t && m) return `#/team/${t}/game/${m}/${ui.gameView}`;
  if (ui.view === 'formation' && t && ui.editFid === GAME_SHAPE && m) return `#/team/${t}/game/${m}/shape`;
  if (ui.view === 'formation' && t) return `#/team/${t}/shape/${ui.editFid}`;
  /* The Calendar is the person's, at an address of its own that names no team
     and no club, and says which calendars it shows, so a link, a reload and
     the back button bring back the same ones. */
  if (ui.view === 'calendar') return calSel() === 'club' && calSels().includes('mine') ? '#/calendar/all' : '#/calendar';
  if (['practice', 'roster', 'season', ...SEASON_VIEWS].includes(ui.view) && t) {
    const seg = { practice: 'practice', roster: 'squad', season: 'season', teamstats: 'stats', minutes: 'minutes', attend: 'attendance' }[ui.view];
    return `#/team/${t}/${seg}`;
  }
  if (ui.view === 'games') return '#/games';
  if (ui.view === 'people') return '#/club/people';
  if (ui.view === 'club') return '#/club';
  if (ui.view === 'admin') return '#/club/settings';
  if (ui.view === 'scheduler') return '#/club/scheduler';
  if (ui.view === 'regs') return '#/club/registrations';
  if (ui.view === 'tryout') return '#/club/tryouts';
  if (ui.view === 'comply') return '#/club/compliance';
  if (ui.view === 'mine') return '#/my-players';
  if (ui.view === 'inbox') return '#/messages';
  if (ui.view === 'notes') return '#/whats-new';
  if (ui.view === 'thread' && ui.thread && ui.thread.cid) return `#/messages/with/${sdOther(ui.thread.cid)}`;
  if (ui.view === 'thread' && ui.thread) return `#/messages/${ui.thread.tid}/${ui.thread.fam}`;
  if (ui.view === 'setup') return '#/settings';
  if (ui.view === 'sessions') { const tb = (ui.sess || {}).tab; return '#/training' + (tb && tb !== 'list' && (SESS_TABS[tb] || SESS_SET[tb]) ? '/' + tb : ''); }
  // the Sessions door's Home (DOORS.md); #/training stays the list
  if (ui.view === 'shome') return '#/sessions';
  return '#/';
}

function hashToUi() {
  const p = decodeURIComponent(location.hash.replace(/^#\/?/, '')).split('/').filter(Boolean);
  if (!p.length) return false;
  /* #/club/schedule was the admins' Club schedule and #/club/calendar its next
     address (build 102): All teams on the Calendar. #/my-calendar is what My
     calendar's feed links back to. */
  if (p[0] === 'club' && (p[1] === 'calendar' || p[1] === 'schedule')) { ui.view = 'calendar'; ui.calSel = 'club'; return true; }
  if (p[0] === 'club') { ui.view = p[1] === 'settings' ? 'admin' : p[1] === 'people' ? 'people' : p[1] === 'planner' || p[1] === 'scheduler' ? 'scheduler' : p[1] === 'registrations' ? 'regs' : p[1] === 'tryouts' ? 'tryout' : p[1] === 'compliance' ? 'comply' : 'club'; return true; }
  if (p[0] === 'my-players') { ui.view = 'mine'; return true; }
  if (p[0] === 'games') { ui.view = 'games'; return true; }
  if (p[0] === 'my-calendar') { ui.view = 'calendar'; ui.calSel = 'mine'; return true; }
  if (p[0] === 'calendar') { ui.view = 'calendar'; ui.calSel = p[1] === 'all' ? 'club' : 'mine'; return true; }
  if (p[0] === 'messages') {
    // with a colleague: the address names the other person, never the pair, so it reads the same from either side
    if (p[1] === 'with' && p[2] && me) { ui.view = 'thread'; ui.thread = { cid: sdId(me.uid, p[2]) }; return true; }
    if (p[1] && p[2] && state.teams[p[1]]) { ui.view = 'thread'; ui.thread = { tid: p[1], fam: p[2] }; return true; }
    ui.view = 'inbox'; return true;
  }
  // #/notifications is its address from before build 148
  if (p[0] === 'whats-new' || p[0] === 'notifications') { ui.view = 'notes'; return true; }
  if (p[0] === 'settings') { ui.view = 'setup'; return true; }
  /* #/drill/{key} is a drill a coach sent. The screen stays where it was and
     the drill opens over it, once: the hash goes straight back to the screen's
     own, so Back doesn't open it again. */
  if (p[0] === 'drill' && p[1]) {
    // #/drill/{club tag}/{key}, or #/drill/{key} for a built-in drill, which opens in any club
    // first, so a switch to the link's own club can put the link back on the address
    try { history.replaceState(null, '', location.pathname + location.search + uiToHash()); } catch (e) { }
    if (p[2]) followDrillLink(p.slice(2).join('/'), '', p[1]); else followDrillLink(p[1]);
    return true;
  }
  /* #/training/fields is a tab; #/training/{id} is one session, from a calendar
     file or a message, opened once the screen has drawn. */
  if (p[0] === 'sessions') { ui.view = 'shome'; return true; }
  if (p[0] === 'training') {
    ui.view = 'sessions';
    const u = sessUi();
    if (p[1] && (SESS_TABS[p[1]] || SESS_SET[p[1]])) u.tab = p[1];
    else { u.tab = 'list'; if (p[1]) u.go = p[1]; }
    return true;
  }
  if (p[0] === 'team' && p[1]) {
    if (!state.teams[p[1]]) return false;
    ui.teamId = p[1];
    if (p[2] === 'game' && p[3]) {
      if (!state.matches[p[3]]) return false;
      ui.matchId = p[3]; ui.view = 'game';
      if (p[4] === 'shape') { ui.view = 'formation'; ui.editFid = GAME_SHAPE; return true; }
      if (GAME_VIEWS.includes(p[4])) ui.gameView = p[4];
      return true;
    }
    if (p[2] === 'shape' && p[3]) { ui.editFid = p[3]; ui.view = 'formation'; return true; }
    /* A team's calendar is the person's Calendar with that team on it (alerts
       and calendar files link here); its games were a tab of their own, and
       are its Season now, and its settings ("planning") are on Squad. */
    if (p[2] === 'calendar') { calShowTeam(p[1]); return true; }
    const back = { games: 'season', practice: 'practice', squad: 'roster', season: 'season', planning: 'roster', stats: 'teamstats', minutes: 'minutes', attendance: 'attend' }[p[2]];
    ui.view = back || 'season';
    return true;
  }
  return false;
}

/* A family's Home is her child's team with her child on top (UX-REVIEW.md,
   1.2, build 142; the team's Season since build 153): what she opens the app
   for is there, the next thing with Going / Not going on it. So the app
   opened with no address of its own (the icon on her home screen, a typed
   address) lands there, whatever was open last, while a link or a reload
   keeps the screen it names. Staff keep what was open last, as before.
   Whether she is family is known from the phone's copy at once, or for a new
   phone once the club has been read (connected()); a tap before then is her
   choosing somewhere, and the landing is called off (onAct). */
let landHome = false;
function landNow() {
  if (!landHome) return;
  // the door she last stood in, or where she starts (DOORS.md): the screen being left behind does not decide it
  if (navKind() === 'family') { landHome = false; ui.door = ui.door && hasDoor(ui.door) ? ui.door : defaultDoor(); ui.view = ui.door === 'sessions' ? 'shome' : homeView(); ui.thread = null; return; }
  // nothing more is coming to change her mind: no club to read, or it has been read
  if (wsRead || !fbConfig().apiKey) landHome = false;
}

let routing = false;
/* pushState, not replaceState: every move needs its own history entry or the
   phone's back gesture walks straight out of the app instead of up a level.
   But only a move she made gets one. Whether the address changed because she
   tapped something is the test, not whether the app has booted: it used to
   be a `booted` flag set only when the address changed, so a page opened on
   an address it kept (a reload, a link, the home-screen icon) replaced her
   first move instead of adding it, and Back left the site a page early. And
   a screen the app moves her off by itself (a tab her role doesn't get, a
   game whose Subs were put away, the club read arriving) replaces, or Back
   lands on the old address, is moved off it again and pushes it back: a loop
   she can't Back out of. `tapped` is set up beside onAct, ahead of every
   click handler. */
/* A sheet has a history entry of its own, at the same address, so Back closes
   it rather than moving the screen behind it while it stays open on top.
   Closed any other way (the scrim, Escape, a button), the entry is taken back
   off with history.back(), a tick later: if the same tap goes on to another
   screen, that screen takes over the sheet's entry instead (syncHash), so
   closing a sheet and moving on is one Back, not two. */
let sheetEntry = false, sheetBack = false, ignorePops = 0;
function sheetEntered() {
  if (sheetBack) { sheetBack = false; return; }   // one sheet closed for the next: same entry
  if (sheetEntry || typeof history === 'undefined' || !history.pushState) return;
  try { history.pushState({ sheet: 1 }, '', location.pathname + location.search + location.hash); sheetEntry = true; } catch (e) { }
}
function sheetLeft() {
  if (!sheetEntry || sheetBack) return;
  sheetBack = true;
  setTimeout(() => {
    if (!sheetBack) return;
    sheetBack = false; sheetEntry = false; ignorePops++;
    try { history.back(); } catch (e) { ignorePops--; }
  }, 0);
}
function syncHash() {
  if (typeof history === 'undefined' || !history.pushState) return;
  const want = uiToHash();
  if (location.hash === want) return;
  routing = true;
  const url = location.pathname + location.search + want;
  if (sheetBack) { sheetBack = false; sheetEntry = false; history.replaceState(null, '', url); }
  else if (tapped && !sheetEntry) history.pushState(null, '', url);
  // the app moving her by itself, or the screen behind an open sheet: the entry stays whose it was
  else history.replaceState(history.state, '', url);
  tapped = false;
  setTimeout(() => { routing = false; }, 0);
}
const avEl = $('#avatar');
if (avEl) avEl.addEventListener('click', () => (me ? sheetAccount() : sheetSignIn()));
// a tab brought back to the front has now read what arrived while it was behind
if (typeof document !== 'undefined' && document.addEventListener)
  document.addEventListener('visibilitychange', () => { if (!document.hidden && (ui.view === 'inbox' || ui.view === 'thread')) render(); });
// Esc on a computer, or the browser's own way out: the frame comes back with the chrome
if (typeof document !== 'undefined' && document.addEventListener)
  document.addEventListener('fullscreenchange', () => { if (!document.fullscreenElement && ui.trackFull) { ui.trackFull = false; render(); } });

if (typeof window !== 'undefined' && window.addEventListener) {
  const backOrForward = e => {
    if (e && e.type === 'popstate') {
      if (ignorePops) { ignorePops--; return; }   // a closed sheet's entry, taken off
      /* Back with a sheet open closes it. Its entry is gone now, so a sheet
         reopened gets a fresh one; and the screen only moves if the entry
         Back landed on was another screen's. */
      sheetEntry = false; sheetBack = false;
      if (!$('#sheet').hidden) { $('#sheet').hidden = true; $('#scrim').hidden = true; }
    }
    if (routing) return;
    const want = uiToHash();
    if (location.hash === want) return;
    if (hashToUi()) { routing = true; render(); setTimeout(() => { routing = false; }, 0); }
  };
  window.addEventListener('popstate', backOrForward);
  window.addEventListener('hashchange', backOrForward);
}

/* ---------------- boot ---------------- */
captureInvite();
